import { defineStore } from 'pinia';

export const useAIChatStore = defineStore('AIChat', {
    state: () => ({
        // 持久化参数，不会被清空（如模型选择）
        persistentParams: {
            model: null,
            isThinking: null, // Think模式应该是持久化的用户偏好
            enable_search: null, // DeepSearch启用状态，持久化的用户偏好
        },
        // 临时参数，发送消息后会被清空（如消息内容）
        temporaryParams: {
            content: null,
            files: null,
        },
    }),
    
    actions: {
        // 设置AI提问参数
        setAIChatParams(params) {
            // 分离持久化参数和临时参数
            if (params.model !== undefined) {
                this.persistentParams.model = params.model;
            }
            if (params.isThinking !== undefined) {
                this.persistentParams.isThinking = params.isThinking;
            }
            if (params.enable_search !== undefined) {
                this.persistentParams.enable_search = params.enable_search;
            }
            
            // 设置临时参数
            const { model, isThinking, enable_search, ...tempParams } = params;
            Object.keys(tempParams).forEach(key => {
                if (this.temporaryParams.hasOwnProperty(key)) {
                    this.temporaryParams[key] = tempParams[key];
                }
            });
        },
        
        // 获取AI提问参数
        getAIChatParams() {
            return {
                ...this.persistentParams,
                ...this.temporaryParams,
            };
        },
        
        // 清空临时参数，保留持久化参数
        clearAIChatParams() {
            this.temporaryParams = {
                content: null,
                files: null,
            };
        },
        
        // 完全清空所有参数（包括持久化参数）
        clearAllParams() {
            this.persistentParams = {
                model: null,
                isThinking: null,
                enable_search: null,
            };
            this.temporaryParams = {
                content: null,
                files: null,
            };
        },
    }
}); 